Method.Source:
    /// <summary>
    /// Retrieves the first record of the table based on condition
    /// </summary>
    /// <param name = "_custAccount"> Customer account number</param>
    /// <param name = "_forUpdate"> A Boolean value that determines whether the RecId of orign should be selected for update; optional.</param>
    /// <returns> The table record </returns>
    static METCustTobaccoLicenseTable find(CustAccount   _custAccount, boolean  _forUpdate = false)
    {
        METCustTobaccoLicenseTable custTobaccoLicenseTable;

        if (_custAccount)
        {
            if (_forUpdate)
            {
                custTobaccoLicenseTable.selectForUpdate(_forUpdate);
            }

            select firstonly custTobaccoLicenseTable
                index hint CustLicenceIdx
                where custTobaccoLicenseTable.CustomerNumber == _custAccount;
        }

        return custTobaccoLicenseTable;
    }

/// <summary>
/// Searches for the first record of the table based on condition
/// </summary>
/// <param name = "_custAccount"> Customer account number</param>
/// <returns> A Boolean value "Yes" if record exists, else "No" </returns>
static boolean exist(CustAccount _custAccount)
{
    return _custAccount && (select firstonly RecId from METCustTobaccoLicenseTable
                                index hint CustLicenceIdx
                                where METCustTobaccoLicenseTable.CustomerNumber == _custAccount).RecId != 0;
}

    /// <summary>
    /// Customer Liquor validations on modified fields
    /// </summary>
    /// <param name = "_fieldId">Field number of the modified column</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);
        switch(_fieldId)
        {
            case fieldnum(METCustTobaccoLicenseTable, CustomerNumber):
                if(CustTable::exist(this.CustomerNumber))
                {
                    this.CustomerName = CustTable::find(this.CustomerNumber).name();
                }
                break;

        }
    }

/// <summary>
/// Initialize default values of the table
/// </summary>
public void initValue()
{
    super();
    this.SendNotificationsTo = METCustParameters::Find().CustDefaultEmailPurpose;
}

    /// <summary>
    /// Mandatory values are validated
    /// </summary>
    /// <returns>True, if all the validations are cleared, else False.</returns>
    public boolean validateWrite()
    {
        boolean ret;
        CustTable   custTable;
    
        ret = super();

        custTable = CustTable::find(this.CustomerNumber, false);
        if(LogisticsAddressState::find(custTable.PartyCountry, custTable.PartyState).METTobaccoLicenceExpiryDateRequired && this.TobaccoLicenceExpiry == dateNull())
        {
            ret = ret && checkFailed("@MET:METTobaccoLicExpiryError");
        }
    
        return ret;
    }
